155	/****************************************************************************
156	 * Name: media_codec_scan_devices
157	 *
158	 * Description:
159	 *   Scan /dev for video* nodes, check V4L2_CAP_VIDEO_M2M capability,
160	 *   enumerate supported compressed formats to build codec registry.
161	 *
162	 ****************************************************************************/
163	
164	static void media_codec_scan_devices(void)
165	{
166	    DIR* dir;
167	    struct dirent* entry;
168	    char path[sizeof("/dev/") + NAME_MAX];
169	
170	    g_media_codec_registry_count = 0;
171	
172	    dir = opendir("/dev");
173	    if (dir == NULL) {
174	        MEDIA_ERR("opendir /dev failed: %d\n", errno);
175	        return;
176	    }
177	
178	    while ((entry = readdir(dir)) != NULL) {
179	        struct v4l2_capability cap = { 0 };
180	        struct v4l2_fmtdesc fmtdesc = { 0 };
181	        int fd;
182	
183	        if (strncmp(entry->d_name, MEDIA_CODEC_DEV_PREFIX,
184	                strlen(MEDIA_CODEC_DEV_PREFIX))
185	            != 0) {
186	            continue;
187	        }
188	
189	        snprintf(path, sizeof(path), "/dev/%s", entry->d_name);
190	        fd = open(path, O_RDWR | O_CLOEXEC);
191	        if (fd < 0) {
192	            continue;
193	        }
194	
195	        /* Check M2M capability */
196	
197	        if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0 || !(cap.capabilities & V4L2_CAP_VIDEO_M2M)) {
198	            close(fd);
199	            continue;
200	        }
201	
202	        /* OUTPUT queue compressed format → Decoder */
203	
204	        fmtdesc.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
205	        for (fmtdesc.index = 0; ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0;
206	             fmtdesc.index++) {
207	            if (media_codec_is_compressed_fmt(fmtdesc.pixelformat)) {
208	                media_codec_register_device(path, MEDIA_CODEC_DECODER,
209	                    fmtdesc.pixelformat);
210	            }
211	        }
212	
213	        /* CAPTURE queue compressed format → Encoder */
214	
215	        memset(&fmtdesc, 0, sizeof(fmtdesc));
216	        fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
217	        for (fmtdesc.index = 0; ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0;
218	             fmtdesc.index++) {
219	            if (media_codec_is_compressed_fmt(fmtdesc.pixelformat)) {
220	                media_codec_register_device(path, MEDIA_CODEC_ENCODER,
221	                    fmtdesc.pixelformat);
222	            }
223	        }
224	
225	        close(fd);
226	    }
227	
228	    closedir(dir);
229	}
